import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";
import { AllowancePillView } from "@/components/history/AllowancePillView";
import type { QuotaAllowance, QuotaSnapshot } from "@/lib/quota-snapshot";
import { PLANS } from "@/lib/plans";
import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";

type Gated = Extract<QuotaSnapshot, { mode: "gated" }>;
function allowance(limit: number, sent = 0, reserved = 0): QuotaAllowance {
  return {
    limit,
    sent,
    reserved,
    used: sent + reserved,
    remaining: limit - sent - reserved,
    startsAt: "2026-11-01T00:00:00Z",
    endsAt: null,
    resetsAt: null,
  };
}
function fixture(plan: "FREE" | "PAID" = "FREE"): Gated {
  return {
    mode: "gated",
    plan,
    sendingAllowed: true,
    pauseReason: null,
    used: 0,
    limit: PLANS[plan].dailyEmails,
    daily: allowance(PLANS[plan].dailyEmails),
    monthly: allowance(PLANS[plan].monthlyEmails),
    // This presentation component never reads entitlements.
    entitlements: {} as Gated["entitlements"],
  };
}
const render = (quota?: QuotaSnapshot) =>
  renderToStaticMarkup(createElement(AllowancePillView, { quota }));

describe("History allowance mini meters", () => {
  it("renders Free segments and monthly remaining using the live limits", () => {
    const quota = fixture();
    quota.monthly = allowance(PLANS.FREE.monthlyEmails, 1);
    const html = render(quota);
    expect(html).toContain('aria-label="Email allowances"');
    expect(html.match(/data-filled="true"/g)).toHaveLength(3);
    expect(html).toContain('aria-valuemax="3" aria-valuenow="3"');
    expect(html).toContain('aria-valuemax="15" aria-valuenow="14"');
    expect(html).toContain('href="/usage#allowances"');
  });
  it("uses Premium bars and accounts for reservations", () => {
    const quota = fixture("PAID");
    quota.daily = allowance(20, 2, 1);
    quota.monthly = allowance(300, 58, 1);
    const html = render(quota);
    expect(html).not.toContain("data-filled");
    expect(html).toContain('aria-valuemax="20" aria-valuenow="17"');
    expect(html).toContain('aria-valuemax="300" aria-valuenow="241"');
    expect(html).toContain("width:85%");
    expect(html).toContain("width:80.33333333333333%");
  });
  it("clamps values, handles zero limits, and does not assume fixed plan limits", () => {
    const quota = fixture();
    quota.daily = allowance(4, -2);
    quota.monthly = allowance(0, 5);
    const html = render(quota);
    expect(html.match(/data-filled="true"/g)).toHaveLength(4);
    expect(html).toContain('aria-valuemax="4" aria-valuenow="4"');
    expect(html).toContain('aria-valuemax="0" aria-valuenow="0"');
    expect(html).toContain("width:0%");
    expect(html).not.toMatch(/NaN|Infinity|aria-valuenow="-/);
  });
  it("distinguishes Free one-left, Premium 10%, and empty states", () => {
    const quota = fixture();
    quota.daily = allowance(3, 2);
    expect(render(quota)).toMatch(
      /aria-label="Daily emails left" data-low="true"/,
    );
    quota.daily = allowance(3, 3);
    expect(render(quota)).toContain('aria-valuenow="0"');
    expect(render(quota)).not.toContain('data-filled="true"');
    const paid = fixture("PAID");
    paid.daily = allowance(20, 18);
    expect(render(paid)).toMatch(
      /aria-label="Daily emails left" data-low="true"/,
    );
    paid.daily = allowance(20, 17);
    expect(render(paid)).not.toMatch(
      /aria-label="Daily emails left" data-low="true"/,
    );
  });
  it("preserves unavailable, paused and legacy states", () => {
    const quota = fixture();
    quota.monthly.startsAt = null;
    expect(render(quota)).toContain("Monthly allowance unavailable");
    expect(render(quota)).not.toContain('aria-label="Monthly emails left"');
    quota.sendingAllowed = false;
    expect(render(quota)).toContain("Sending paused.");
    expect(render(quota)).toContain('href="/usage#allowances"');
    const legacy = render({
      mode: "legacy",
      used: 2,
      limit: DAILY_EMAIL_LIMIT,
    });
    expect(legacy).toContain("remaining per rolling 24 hours");
    expect(legacy).not.toContain('role="meter"');
  });
  it("renders loading placeholders without reporting zero allowance", () => {
    const html = render();
    expect(html).toContain('aria-busy="true"');
    expect(html).toContain("Loading email allowances");
    expect(
      html.match(/data-slot="allowance-placeholder-number"/g),
    ).toHaveLength(2);
    expect(html.match(/data-slot="allowance-placeholder-meter"/g)).toHaveLength(
      2,
    );
    expect(html).not.toContain("aria-valuenow");
    expect(html).not.toContain("left");
  });
});
